"""Unique persona per creator, generated by the Speel "Corpo Girl" workflow.

Flow (French UI, like the rest of the bot):
  /persona photo genre  →  Speel starts the Femme/Homme branch (22 images, ~2–3 min)
  → the bot follows progress in the creator's private clips thread
  → gallery + "Régénérer une image" (1 fois par image) + "Valider mon persona"
  → validated images become the creator's avatar pack for every carousel.

Speel is the source of truth (one paid run per Discord user, survives bot redeploys).
Env: SPEEL_API_URL, PERSONA_API_SECRET.
"""

from __future__ import annotations

import asyncio
import os
import time
from pathlib import Path
from typing import Any

import aiohttp
import discord
from discord import app_commands

from staff import is_staff_member

PERSONA_COLOR = 0xA78BFA
DONE_COLOR = 0x22C55E
POLL_SECONDS = 15
WATCH_TIMEOUT_SECONDS = 25 * 60
EMBEDS_PER_MESSAGE = 10
NEGATIVE_CACHE_SECONDS = 300

_client: discord.Client | None = None
_watchers: dict[int, asyncio.Task] = {}
_shown: dict[int, dict[int, str]] = {}
_pack_cache: dict[int, tuple[str | None, float]] = {}


# ---------------------------------------------------------------------------
# Config / API
# ---------------------------------------------------------------------------

def _api_base() -> str:
    return os.getenv("SPEEL_API_URL", "").strip().rstrip("/")


def _api_secret() -> str:
    return os.getenv("PERSONA_API_SECRET", "").strip()


def is_configured() -> bool:
    return bool(_api_base() and _api_secret())


class PersonaApiError(Exception):
    def __init__(self, message: str, status: int = 0, code: str = "") -> None:
        super().__init__(message)
        self.status = status
        self.code = code


async def _api(method: str, path: str, payload: dict | None = None) -> dict:
    if not is_configured():
        raise PersonaApiError("Persona non configuré (SPEEL_API_URL / PERSONA_API_SECRET).", 503, "not_configured")
    url = f"{_api_base()}/api/persona/runs{path}"
    headers = {"Authorization": f"Bearer {_api_secret()}"}
    timeout = aiohttp.ClientTimeout(total=150)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.request(method, url, json=payload, headers=headers) as resp:
            try:
                body = await resp.json(content_type=None)
            except (aiohttp.ContentTypeError, ValueError):
                body = {}
            if resp.status >= 400:
                raise PersonaApiError(
                    str((body or {}).get("error") or f"HTTP {resp.status}"),
                    resp.status,
                    str((body or {}).get("code") or ""),
                )
            return (body or {}).get("data") or {}


async def get_run(user_id: int) -> dict | None:
    try:
        return await _api("GET", f"/{user_id}")
    except PersonaApiError as exc:
        if exc.status == 404:
            return None
        raise


# ---------------------------------------------------------------------------
# Eligibility
# ---------------------------------------------------------------------------

def _is_approved_creator(user_id: int) -> bool:
    import registration

    registration._load_store()
    record = registration._registrations.get(str(user_id)) or {}
    return record.get("status") == "approved"


def can_create_persona(member: discord.abc.User) -> bool:
    return is_staff_member(member) or _is_approved_creator(member.id)


def _can_manage(interaction: discord.Interaction, owner_id: int) -> bool:
    return interaction.user.id == owner_id or is_staff_member(interaction.user)


# ---------------------------------------------------------------------------
# Avatar pack (validated persona → carousel avatars)
# ---------------------------------------------------------------------------

def persona_pack_name(user_id: int, gender: str) -> str:
    # Gender prefix keeps the carousel's male/female photo filtering working.
    prefix = "homme" if gender == "homme" else "femme"
    return f"{prefix}_persona_{user_id}"


def _avatars_dir() -> Path:
    from carousel.generate_carousel import AVATARS_DIR

    return AVATARS_DIR


def local_persona_pack(user_id: int) -> str | None:
    """Pack already downloaded on this machine (sync, safe before an interaction response)."""
    root = _avatars_dir()
    for gender in ("femme", "homme"):
        name = persona_pack_name(user_id, gender)
        folder = root / name
        if folder.is_dir() and any(folder.iterdir()):
            return name
    return None


async def _download_pack(run: dict) -> str | None:
    user_id = int(run["externalId"])
    name = persona_pack_name(user_id, run.get("gender", "femme"))
    folder = _avatars_dir() / name
    slots = [s for s in run.get("slots") or [] if s.get("status") == "done" and s.get("imageUrl")]
    if not slots:
        return None
    folder.mkdir(parents=True, exist_ok=True)
    wanted = {f"persona_{int(s['index']):02d}": s["imageUrl"] for s in slots}
    existing = {p.stem: p for p in folder.iterdir() if p.is_file()}
    timeout = aiohttp.ClientTimeout(total=60)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        for stem, url in wanted.items():
            if stem in existing:
                continue
            ext = Path(url.split("?")[0]).suffix.lower() or ".png"
            if ext not in (".png", ".jpg", ".jpeg", ".webp"):
                ext = ".png"
            try:
                async with session.get(url) as resp:
                    if resp.status != 200:
                        continue
                    (folder / f"{stem}{ext}").write_bytes(await resp.read())
            except (aiohttp.ClientError, asyncio.TimeoutError, OSError) as exc:
                print(f"[PERSONA] Download failed {url}: {exc}")
    return name if any(folder.iterdir()) else None


async def ensure_persona_pack(user_id: int) -> str | None:
    """Validated persona pack name for this user (downloads it if missing), else None."""
    local = local_persona_pack(user_id)
    if local:
        return local
    cached = _pack_cache.get(user_id)
    if cached and cached[1] > time.time():
        return cached[0]
    pack: str | None = None
    if is_configured():
        try:
            run = await get_run(user_id)
            if run and run.get("status") == "validated":
                pack = await _download_pack(run)
        except (PersonaApiError, aiohttp.ClientError, asyncio.TimeoutError) as exc:
            print(f"[PERSONA] ensure pack failed for {user_id}: {exc}")
    _pack_cache[user_id] = (pack, time.time() + NEGATIVE_CACHE_SECONDS)
    return pack


# ---------------------------------------------------------------------------
# Embeds
# ---------------------------------------------------------------------------

def _progress_embed(run: dict) -> discord.Embed:
    done = int(run.get("done") or 0)
    total = int(run.get("total") or 0)
    return discord.Embed(
        title="🧬 Création de ton persona",
        description=(
            f"⏳ **{done}/{total} images prêtes…**\n"
            "Ça prend environ 2–3 minutes. Tu peux fermer Discord, "
            "la galerie arrivera ici automatiquement."
        ),
        color=PERSONA_COLOR,
    )


def _image_embeds(slots: list[dict], *, regenerated: bool = False) -> list[discord.Embed]:
    embeds = []
    for slot in slots:
        title = f"#{slot['index']}" + (" — nouvelle version" if regenerated else "")
        embed = discord.Embed(title=title, color=PERSONA_COLOR)
        embed.set_image(url=slot["imageUrl"])
        embeds.append(embed)
    return embeds


def _control_embed(run: dict) -> discord.Embed:
    total = int(run.get("total") or 0)
    done = int(run.get("done") or 0)
    failed = [s for s in run.get("slots") or [] if s.get("status") == "failed"]
    regen_left = [s for s in run.get("slots") or [] if s.get("canRegenerate") and s.get("status") == "done"]
    lines = [
        f"✅ **{done}/{total} images générées.**",
        "",
        "Une image ne te plaît pas ? Choisis son numéro dans le menu pour la **régénérer** "
        "(**1 seule fois par image**).",
    ]
    if failed:
        nums = ", ".join(f"#{s['index']}" for s in failed)
        lines.append(f"❌ Échec : {nums} — tu peux les relancer gratuitement via le menu.")
    lines += [
        "",
        f"Régénérations encore possibles : **{len(regen_left)}** image(s).",
        "Quand tout est bon, clique sur **Valider mon persona** : il sera utilisé "
        "dans tous tes carrousels.",
    ]
    return discord.Embed(title="🧬 Ton persona est prêt", description="\n".join(lines), color=DONE_COLOR)


def _validated_embed(run: dict) -> discord.Embed:
    return discord.Embed(
        title="✅ Persona validé",
        description=(
            f"**{run.get('done', 0)} images** enregistrées comme ton avatar.\n"
            "Tes prochains carrousels (bouton **Générer du contenu**) utiliseront ton persona."
        ),
        color=DONE_COLOR,
    )


# ---------------------------------------------------------------------------
# Components (persistent across restarts)
# ---------------------------------------------------------------------------

def _regen_options(run: dict) -> list[discord.SelectOption]:
    options = []
    for slot in run.get("slots") or []:
        if not slot.get("canRegenerate"):
            continue
        failed = slot.get("status") == "failed"
        options.append(
            discord.SelectOption(
                label=f"Image #{slot['index']}" + (" (échec, gratuit)" if failed else ""),
                value=str(slot["index"]),
            )
        )
    return options[:25]


class PersonaRegenSelect(
    discord.ui.DynamicItem[discord.ui.Select],
    template=r"jobshift_persona_regen:(?P<user_id>\d+)",
):
    def __init__(self, user_id: int, options: list[discord.SelectOption] | None = None) -> None:
        self.user_id = user_id
        opts = options or [discord.SelectOption(label="Aucune image à régénérer", value="0")]
        super().__init__(
            discord.ui.Select(
                custom_id=f"jobshift_persona_regen:{user_id}",
                placeholder="🔁 Régénérer une image…",
                min_values=1,
                max_values=1,
                options=opts,
                disabled=not options,
            )
        )

    @classmethod
    async def from_custom_id(cls, interaction, item, match):  # type: ignore[override]
        return cls(int(match["user_id"]), options=list(getattr(item, "options", []) or []) or None)

    async def callback(self, interaction: discord.Interaction) -> None:
        if not _can_manage(interaction, self.user_id):
            await interaction.response.send_message("Ce persona n’est pas le tien.", ephemeral=True)
            return
        values = (interaction.data or {}).get("values") or []
        slot = int(values[0]) if values and str(values[0]).isdigit() else 0
        if slot < 1:
            await interaction.response.send_message("Aucune image sélectionnée.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True, thinking=True)
        try:
            await _api("POST", f"/{self.user_id}/regenerate", {"slot": slot})
        except PersonaApiError as exc:
            await interaction.followup.send(f"❌ {_fr_error(exc)}", ephemeral=True)
            return
        _start_watcher(self.user_id, _thread_id(interaction), regenerated=True)
        await interaction.followup.send(
            f"🔁 Image **#{slot}** en cours de régénération (≈1 min). Elle arrivera ici.",
            ephemeral=True,
        )


class PersonaActionButton(
    discord.ui.DynamicItem[discord.ui.Button],
    template=r"jobshift_persona:(?P<action>validate|refresh):(?P<user_id>\d+)",
):
    def __init__(self, action: str, user_id: int) -> None:
        self.action = action
        self.user_id = user_id
        if action == "validate":
            button = discord.ui.Button(
                label="Valider mon persona",
                emoji="✅",
                style=discord.ButtonStyle.success,
                custom_id=f"jobshift_persona:validate:{user_id}",
            )
        else:
            button = discord.ui.Button(
                label="Actualiser",
                emoji="🔄",
                style=discord.ButtonStyle.secondary,
                custom_id=f"jobshift_persona:refresh:{user_id}",
            )
        super().__init__(button)

    @classmethod
    async def from_custom_id(cls, interaction, item, match):  # type: ignore[override]
        return cls(match["action"], int(match["user_id"]))

    async def callback(self, interaction: discord.Interaction) -> None:
        if not _can_manage(interaction, self.user_id):
            await interaction.response.send_message("Ce persona n’est pas le tien.", ephemeral=True)
            return
        if self.action == "validate":
            await interaction.response.send_message(
                "Une fois validé, tu ne pourras plus régénérer d’images. On valide ?",
                view=_ConfirmValidateView(self.user_id),
                ephemeral=True,
            )
            return
        await interaction.response.defer(ephemeral=True, thinking=True)
        try:
            run = await get_run(self.user_id)
        except PersonaApiError as exc:
            await interaction.followup.send(f"❌ {_fr_error(exc)}", ephemeral=True)
            return
        if not run:
            await interaction.followup.send("Aucun persona trouvé.", ephemeral=True)
            return
        if run.get("status") == "generating":
            _start_watcher(self.user_id, _thread_id(interaction))
            await interaction.followup.send(
                f"⏳ {run.get('done', 0)}/{run.get('total', 0)} images prêtes…", ephemeral=True
            )
            return
        _shown.pop(self.user_id, None)
        await _post_gallery(_here(interaction), run)
        await interaction.followup.send("Galerie à jour.", ephemeral=True)


class _ConfirmValidateView(discord.ui.View):
    def __init__(self, user_id: int) -> None:
        super().__init__(timeout=120)
        self.user_id = user_id

    @discord.ui.button(label="Oui, valider", style=discord.ButtonStyle.success, emoji="✅")
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(content="⏳ Validation…", view=None)
        try:
            run = await _api("POST", f"/{self.user_id}/validate")
        except PersonaApiError as exc:
            await interaction.edit_original_response(content=f"❌ {_fr_error(exc)}")
            return
        _pack_cache.pop(self.user_id, None)
        pack = await _download_pack(run)
        if pack:
            _pack_cache[self.user_id] = (pack, time.time() + 10 * 365 * 86400)
        await interaction.edit_original_response(content="✅ Persona validé.")
        await _Destination(_here(interaction), self.user_id).send(embed=_validated_embed(run))


def _here(interaction: discord.Interaction) -> discord.abc.Messageable | None:
    """Channel of a gallery button: the creator's thread, or their DMs (fallback delivery)."""
    channel = interaction.channel
    return channel if isinstance(channel, (discord.Thread, discord.DMChannel)) else None


def _thread_id(interaction: discord.Interaction) -> int | None:
    channel = interaction.channel
    return channel.id if isinstance(channel, discord.Thread) else None


def _control_view(run: dict) -> discord.ui.View:
    user_id = int(run["externalId"])
    view = discord.ui.View(timeout=None)
    if run.get("status") != "validated":
        view.add_item(PersonaRegenSelect(user_id, _regen_options(run) or None))
        view.add_item(PersonaActionButton("validate", user_id))
    view.add_item(PersonaActionButton("refresh", user_id))
    return view


# ---------------------------------------------------------------------------
# Watching a run
# ---------------------------------------------------------------------------

class _Destination:
    """Thread first; falls back to the creator's DMs when the bot cannot post in the thread."""

    def __init__(self, thread: discord.abc.Messageable | None, user_id: int) -> None:
        self.thread = thread
        self.user_id = user_id
        self._dm: discord.abc.Messageable | None = None

    async def _dm_channel(self) -> discord.abc.Messageable | None:
        if self._dm is None and _client is not None:
            try:
                user = _client.get_user(self.user_id) or await _client.fetch_user(self.user_id)
                self._dm = await user.create_dm()
            except discord.HTTPException:
                return None
        return self._dm

    async def send(self, *args: Any, **kwargs: Any) -> discord.Message | None:
        if self.thread is not None:
            try:
                return await self.thread.send(*args, **kwargs)
            except discord.HTTPException as exc:
                print(f"[PERSONA] Thread send failed for {self.user_id}, using DM: {exc}")
                self.thread = None
        dm = await self._dm_channel()
        if dm is None:
            return None
        try:
            return await dm.send(*args, **kwargs)
        except discord.HTTPException as exc:
            print(f"[PERSONA] DM send failed for {self.user_id}: {exc}")
            return None


async def _post_gallery(thread: discord.abc.Messageable | None, run: dict, *, regenerated: bool = False) -> None:
    user_id = int(run["externalId"])
    dest = thread if isinstance(thread, _Destination) else _Destination(thread, user_id)
    shown = _shown.setdefault(user_id, {})
    fresh = [
        s
        for s in run.get("slots") or []
        if s.get("status") == "done" and s.get("imageUrl") and shown.get(int(s["index"])) != s["imageUrl"]
    ]
    embeds = _image_embeds(fresh, regenerated=regenerated)
    for start in range(0, len(embeds), EMBEDS_PER_MESSAGE):
        await dest.send(embeds=embeds[start : start + EMBEDS_PER_MESSAGE])
    for s in fresh:
        shown[int(s["index"])] = s["imageUrl"]
    if run.get("status") == "validated":
        await dest.send(embed=_validated_embed(run), view=_control_view(run))
    else:
        await dest.send(f"<@{user_id}>", embed=_control_embed(run), view=_control_view(run))


async def _resolve_thread(thread_id: int) -> discord.Thread | None:
    if _client is None:
        return None
    channel = _client.get_channel(thread_id)
    if channel is None:
        try:
            channel = await _client.fetch_channel(thread_id)
        except discord.HTTPException:
            return None
    return channel if isinstance(channel, discord.Thread) else None


async def _watch(
    user_id: int,
    thread_id: int | None,
    *,
    regenerated: bool,
    progress_ref: tuple[int, int] | None,
) -> None:
    thread = await _resolve_thread(thread_id) if thread_id else None
    dest = _Destination(thread, user_id)
    progress: discord.PartialMessage | None = None
    if progress_ref and _client is not None:
        channel_id, message_id = progress_ref
        progress = _client.get_partial_messageable(channel_id).get_partial_message(message_id)
    deadline = time.time() + WATCH_TIMEOUT_SECONDS
    last_done = -1
    while time.time() < deadline:
        try:
            run = await get_run(user_id)
        except (PersonaApiError, aiohttp.ClientError, asyncio.TimeoutError) as exc:
            print(f"[PERSONA] poll failed for {user_id}: {exc}")
            await asyncio.sleep(POLL_SECONDS)
            continue
        if run is None:
            return
        if run.get("status") != "generating":
            if progress is not None:
                try:
                    await progress.delete()
                except discord.HTTPException:
                    pass
            await _post_gallery(dest, run, regenerated=regenerated)
            return
        done = int(run.get("done") or 0)
        if progress is not None and done != last_done and not regenerated:
            try:
                await progress.edit(embed=_progress_embed(run))
            except discord.HTTPException:
                pass
        last_done = done
        await asyncio.sleep(POLL_SECONDS)
    await dest.send(
        f"<@{user_id}> ⏳ La génération prend plus de temps que prévu. "
        "Clique sur **Actualiser** plus tard.",
        view=_control_view({"externalId": str(user_id), "status": "generating"}),
    )


def _start_watcher(
    user_id: int,
    thread_id: int | None,
    *,
    regenerated: bool = False,
    progress_ref: tuple[int, int] | None = None,
) -> None:
    current = _watchers.get(user_id)
    if current and not current.done():
        return

    async def runner() -> None:
        try:
            await _watch(user_id, thread_id, regenerated=regenerated, progress_ref=progress_ref)
        except Exception as exc:
            print(f"[PERSONA] watcher crashed for {user_id}: {exc}")
        finally:
            _watchers.pop(user_id, None)

    _watchers[user_id] = asyncio.create_task(runner())


def _fr_error(exc: PersonaApiError) -> str:
    return {
        "already_exists": "Tu as déjà créé ton persona (1 seule génération par personne).",
        "regen_limit": "Cette image a déjà été régénérée (1 seule fois par image).",
        "pending": "Cette image est encore en cours de génération, patiente un peu.",
        "validated": "Ton persona est déjà validé, il ne peut plus être modifié.",
        "not_image": "Le fichier n’est pas une image (jpg, png ou webp).",
        "too_large": "Image trop lourde (15 Mo max).",
        "not_configured": "Le persona n’est pas encore configuré côté serveur. Préviens le staff.",
    }.get(exc.code, str(exc))


# ---------------------------------------------------------------------------
# /persona
# ---------------------------------------------------------------------------

def _content_channel(guild: discord.Guild) -> discord.TextChannel | None:
    from embeds import _load_channel_links

    raw = (_load_channel_links() or {}).get("content_bot", "")
    if not str(raw).isdigit():
        return None
    channel = guild.get_channel(int(raw))
    return channel if isinstance(channel, discord.TextChannel) else None


@app_commands.command(name="persona", description="Crée ton persona unique (1 seule fois) à partir d’une photo")
@app_commands.describe(
    photo="Photo nette, de face, bien éclairée (toi ou une photo trouvée sur Pinterest)",
    genre="Femme ou Homme",
)
@app_commands.choices(
    genre=[
        app_commands.Choice(name="Femme", value="femme"),
        app_commands.Choice(name="Homme", value="homme"),
    ]
)
async def persona_command(
    interaction: discord.Interaction,
    photo: discord.Attachment,
    genre: app_commands.Choice[str],
) -> None:
    if not isinstance(interaction.user, discord.Member) or interaction.guild is None:
        await interaction.response.send_message("Utilise cette commande sur le serveur.", ephemeral=True)
        return
    if not can_create_persona(interaction.user):
        await interaction.response.send_message(
            "Ton inscription doit d’abord être **validée** par l’équipe avant de créer ton persona.",
            ephemeral=True,
        )
        return
    if not (photo.content_type or "").startswith("image/"):
        await interaction.response.send_message("Envoie une **image** (jpg, png ou webp).", ephemeral=True)
        return
    if photo.size > 15 * 1024 * 1024:
        await interaction.response.send_message("Image trop lourde (15 Mo max).", ephemeral=True)
        return
    if not is_configured():
        await interaction.response.send_message(
            "Le persona n’est pas encore configuré côté serveur. Préviens le staff.", ephemeral=True
        )
        return

    await interaction.response.defer(ephemeral=True, thinking=True)
    user_id = interaction.user.id

    try:
        existing = await get_run(user_id)
    except PersonaApiError as exc:
        await interaction.followup.send(f"❌ {_fr_error(exc)}", ephemeral=True)
        return

    thread: discord.Thread | None = None
    content = _content_channel(interaction.guild)
    if content is not None:
        from content_generator import get_or_create_clips_thread

        try:
            thread = await get_or_create_clips_thread(content, interaction.user, mode="single")
        except discord.HTTPException as exc:
            print(f"[PERSONA] Clips thread unavailable for {user_id}, using DM: {exc}")
    dest = _Destination(thread, user_id)

    if existing:
        status = existing.get("status")
        if status == "generating":
            _start_watcher(user_id, thread.id if thread else None)
        else:
            _shown.pop(user_id, None)
            await _post_gallery(dest, existing)
        label = {
            "generating": "en cours de génération",
            "ready": "prêt, en attente de ta validation",
            "validated": "déjà validé",
        }.get(status, status)
        await interaction.followup.send(
            f"Tu as déjà un persona ({label}). Une seule génération par personne. "
            f"Retrouve-le dans {_where(dest, thread)}.",
            ephemeral=True,
        )
        return

    try:
        run = await _api(
            "POST",
            "",
            {
                "externalId": str(user_id),
                "gender": genre.value,
                "selfieUrl": photo.url,
                "meta": {
                    "threadId": str(thread.id) if thread else "",
                    "guildId": str(interaction.guild.id),
                },
            },
        )
    except PersonaApiError as exc:
        await interaction.followup.send(f"❌ {_fr_error(exc)}", ephemeral=True)
        return

    _shown.pop(user_id, None)
    progress = await dest.send(f"{interaction.user.mention}", embed=_progress_embed(run))
    progress_ref = (progress.channel.id, progress.id) if progress is not None else None
    _start_watcher(user_id, dest.thread.id if isinstance(dest.thread, discord.Thread) else None, progress_ref=progress_ref)
    await interaction.followup.send(
        f"✅ C’est parti ! Ton persona ({genre.name}) est en cours de création (≈2–3 min). "
        f"Suis la progression dans {_where(dest, thread)}.",
        ephemeral=True,
    )


def _where(dest: _Destination, thread: discord.Thread | None) -> str:
    if thread is not None and dest.thread is thread:
        return thread.mention
    return "tes messages privés (le bot ne peut pas écrire dans ton fil)"


@app_commands.command(name="persona-reset", description="[Staff] Autorise un créateur à refaire son persona")
@app_commands.describe(membre="Créateur dont le persona doit être supprimé")
async def persona_reset_command(interaction: discord.Interaction, membre: discord.Member) -> None:
    if not is_staff_member(interaction.user):
        await interaction.response.send_message("Réservé au staff.", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True, thinking=True)
    try:
        await _api("DELETE", f"/{membre.id}")
    except PersonaApiError as exc:
        await interaction.followup.send(f"❌ {_fr_error(exc)}", ephemeral=True)
        return
    _pack_cache.pop(membre.id, None)
    _shown.pop(membre.id, None)
    import shutil

    for gender in ("femme", "homme"):
        shutil.rmtree(_avatars_dir() / persona_pack_name(membre.id, gender), ignore_errors=True)
    await interaction.followup.send(
        f"🗑️ Persona de {membre.mention} supprimé. Il peut relancer `/persona` (nouvelle génération payante).",
        ephemeral=True,
    )


# ---------------------------------------------------------------------------
# Wiring
# ---------------------------------------------------------------------------

def register(bot: discord.Client) -> None:
    global _client
    _client = bot
    tree = getattr(bot, "tree", None)
    if tree is not None:
        tree.add_command(persona_command)
        tree.add_command(persona_reset_command)


async def start_persona(bot: discord.Client) -> None:
    """Resume watchers for in-progress runs and prefetch validated packs (no volume on Railway)."""
    global _client
    _client = bot
    if hasattr(bot, "add_dynamic_items"):
        bot.add_dynamic_items(PersonaRegenSelect, PersonaActionButton)
    if not is_configured():
        print("[PERSONA] Disabled (SPEEL_API_URL / PERSONA_API_SECRET missing)")
        return

    async def bootstrap() -> None:
        try:
            runs: list[dict[str, Any]] = await _api("GET", "") or []  # type: ignore[assignment]
        except (PersonaApiError, aiohttp.ClientError, asyncio.TimeoutError) as exc:
            print(f"[PERSONA] Could not list runs: {exc}")
            return
        resumed = 0
        for item in runs:
            ext = str(item.get("externalId") or "")
            if not ext.isdigit():
                continue
            if item.get("status") == "generating":
                thread_id = str((item.get("meta") or {}).get("threadId") or "")
                _start_watcher(int(ext), int(thread_id) if thread_id.isdigit() else None)
                resumed += 1
            elif item.get("status") == "validated":
                await ensure_persona_pack(int(ext))
        print(f"[PERSONA] {len(runs)} run(s), {resumed} watcher(s) resumed")

    asyncio.create_task(bootstrap())
